using StrataLint.Engine;
using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry;

internal sealed class FiniteSimplexBoundarySphereDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Geometry/FiniteSimplexBoundarySphere.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeDocument.Create(
        DefinitionDsl.GeneralHeader(
            "D5/S3/Geometry/FiniteSimplexBoundarySphere",
            "Rational Psi on the literal finite simplex, its full-boundary quotient, the Euclidean unit sphere and the original supported coordinate realization.",
            "finite-simplex-boundary-sphere",
            [Anchor.ParseCanonical("mathlib/module/Mathlib.Analysis.InnerProductSpace.PiL2"),
             Anchor.ParseCanonical("mathlib/module/Mathlib.Topology.Homeomorph.Lemmas")]),
        H("Finite simplex boundary sphere"),
        Blocks(
            Paragraph(Text("This construction starts from the existing finite-product coordinate simplex. Its explicit L2 transport supports the rational sphere map. Both quotients identify the entire boundary, and the ambient bridge retains the original face labels and zero ghost coordinates.")),
            Node("simplex", "Simplex", "Literal Euclidean simplex",
                "The coordinates are nonnegative and sum to one in EuclideanSpace ℝ Λ. The norm used in every sphere calculation is the Euclidean L2 norm.", DescribeRole.Definition),
            Node("boundary", "boundary", "Full face boundary",
                "A boundary witness is a label of Λ at which the coordinate vanishes. A label outside an ambient face is never such a witness.", DescribeRole.Definition),
            Node("boundary-relation", "boundaryRelation", "Full-boundary relation",
                "Two representatives are related exactly when they are equal or both belong to the full boundary.", DescribeRole.Definition),
            Node("boundary-setoid", "boundarySetoid", "Literal collapse relation",
                "Equality-or-both-boundary is reflexive, symmetric and transitive; BoundaryQuotient is its native Setoid quotient.", DescribeRole.Definition),
            Node("coordinate-bridge", "coordinateBridge", "Finite-product topology bridge",
                "WithLp.toLp 2 and WithLp.ofLp restrict to inverse maps between the existing faceSimplex univ and Simplex. Their continuity transports the finite-product topology without equating its function norm with the L2 norm.", DescribeRole.Definition),
            Node("barycenter", "barycenter", "Uniform barycenter",
                "Writing m=card(Λ), every barycenter coordinate is 1/m. For nonempty Λ these coordinates are positive and sum to one.", DescribeRole.Definition),
            Node("pole", "pole", "Normalized pole",
                "Every pole coordinate is 1/sqrt(m). Its squared L2 norm is m/m=1. A vector of coordinate sum zero is orthogonal to this pole.", DescribeRole.Definition),
            Node("psi-raw", "psiRaw", "Rational sphere formula",
                "Put z=x−b, sigma=m min_i x_i, a=‖z‖₂² and D=sigma²+a. The formula is D⁻¹(2 sigma z+(sigma²−a)c), with b the barycenter and c the pole. Every minimum ranges over Λ.", DescribeRole.Definition),
            Node("psi-denominator", "psiDenominator", "Rational denominator",
                "The canonical denominator is sigma squared plus the squared L2 norm of displacement from the barycenter. Its public lower-bound theorem applies to this same term.", DescribeRole.Definition),
            Node("psi-denominator-lower-bound", "psiDenominator_lower_bound", "Uniform denominator estimate",
                "At a minimum label j, m z_j=sigma−1 and z_j²≤‖z‖₂². With r=1−sigma this gives D≥(1−r)²+r²/m². Equivalently, D−1/(m²+1) is the sum of ((m²+1)sigma−1)²/(m²(m²+1)) and a−(sigma−1)²/m², both nonnegative.", DescribeRole.Theorem),
            Node("psi-raw-norm-sq", "psiRaw_norm_sq", "Actual L2 sphere equation",
                "The norm-of-sum expansion has zero cross term because z is orthogonal to c. Its numerator square is 4 sigma² a+(sigma²−a)²=D², so division by the positive denominator gives norm square one.", DescribeRole.Theorem),
            Node("south", "south", "South pole in the metric sphere",
                "The negative of the normalized pole, in the same Euclidean sphere.", DescribeRole.Definition),
            Node("psi", "psi", "Sphere-valued rational map",
                "The rational vector formula is equipped with its norm-one proof; the target is the repository EuclideanSphereJoin.UnitSphere.", DescribeRole.Definition),
            Node("continuous-psi-raw", "continuous_psiRaw", "Continuity at every representative",
                "Finite coordinate minima, displacement and the squared L2 norm are continuous. The denominator has a positive lower bound already for every nonempty label type; reciprocal continuity therefore applies at the barycenter and every boundary point.", DescribeRole.Theorem),
            Node("psi-boundary", "psi_boundary", "Exact full-boundary image",
                "A vanishing face coordinate is equivalent to sigma=0. The denominator then equals the positive displacement square, and Psi is south.", DescribeRole.Theorem),
            Node("psi-south-iff", "psi_south_iff", "Exact south fiber",
                "Pole component minus one forces sigma=0. The attained minimum identifies this with the full boundary, giving the converse as well.", DescribeRole.Theorem),
            Node("psi-eq-iff", "psi_eq_iff", "Exact fibers and scale recovery",
                "Away from south, the pole and tangential components together recover w=(y−alpha c)/(1+alpha)=z/sigma. The finite minimum then supplies sigma(1+m max_i(−w_i))=1, recovering sigma and x=b+sigma w. The pole component alone does not recover sigma. Boundary representatives all have south image.", DescribeRole.Theorem),
            Node("non-south-inverse", "nonSouthInverse", "Explicit inverse away from south",
                "For unit y≠−c let alpha=inner(y,c), v=y−alpha c, M=max_i(−v_i) and kappa=1+alpha+m M. The vector v has sum zero and square norm 1−alpha². Thus M≥0, alpha>−1 and kappa>0. The inverse representative is x=b+v/kappa.", DescribeRole.Definition),
            Node("psi-non-south-inverse", "psi_nonSouthInverse", "Exact inverse substitution",
                "The inverse has min x=(1+alpha)/(m kappa), sigma=(1+alpha)/kappa, z=v/kappa and D=2(1+alpha)/kappa². Substitution makes the tangential coefficient one and the pole coefficient alpha, hence Psi x=v+alpha c=y. This also covers north.", DescribeRole.Theorem),
            Node("psi-surjective", "psi_surjective", "Surjection onto the full sphere",
                "The explicit inverse supplies every non-south point. For south choose a vertex and a different coordinate label; card(Λ)≥2 supplies that label and its coordinate is zero.", DescribeRole.Theorem),
            Node("psi-quotient-map", "psiQuotientMap", "Native quotient descent",
                "The exact equality-or-full-boundary fiber relation makes Quotient.lift well defined, with its literal beta equation and native quotient continuity.", DescribeRole.Definition),
            Node("simplex-boundary-homeomorph", "simplexBoundaryHomeomorph", "Full-boundary quotient homeomorphism",
                "The existing faceSimplex equals the convex hull of its finite set of coordinate vertices and is compact. The coordinate bridge transports compactness to Simplex, and the quotient is compact. Exact fibers and surjectivity give a continuous bijection to the Hausdorff Euclidean sphere; compact-to-Hausdorff supplies inverse continuity including at south.", DescribeRole.Definition),
            Node("reindex-sphere", "reindexSphere", "Norm-preserving sphere reindexing",
                "An equivalence Λ≃Fin((card Λ−1)+1) induces a LinearIsometryEquiv.piLpCongrLeft. Its norm_map and the inverse norm_map justify the sphere restrictions, giving the existing StdSphere(card Λ−1).", DescribeRole.Definition),
            Node("std-index", "stdIndex", "Chosen standard index equivalence",
                "The exact chosen equivalence is equivFin followed by finCongr for card Λ=(card Λ−1)+1, under card Λ≥2.", DescribeRole.Definition),
            Node("simplex-boundary-std-sphere", "simplexBoundaryStdSphere", "Composed StdSphere endpoint",
                "Compose the literal full-boundary quotient homeomorphism with the actual isometric reindexing to StdSphere(card Λ−1).", DescribeRole.Definition),
            Node("face-index", "FaceIndex", "Original face labels",
                "FaceIndex G face is the subtype of original ground labels belonging to face. All minima and maxima continue to range over this subtype.", DescribeRole.Definition),
            Node("zero-extend", "zeroExtend", "Zero extension into the original ground",
                "A face vector retains its value at each original face label and has zero coordinate at every original off-face label.", DescribeRole.Definition),
            Node("zero-extend-apply-ghost", "zeroExtend_apply_ghost", "Ghost evaluation",
                "At a label outside face, zero extension evaluates to zero. Such a label contributes no minimum, maximum or boundary witness.", DescribeRole.Theorem),
            Node("face-coordinate-homeomorph", "faceCoordinateHomeomorph", "Zero-extension and restriction homeomorphism",
                "The map from the face-label simplex to the original ambient faceSimplex is zero extension. Its inverse restricts at each original face label. The two coordinate equations prove both inverse laws, and coordinate projections prove continuity in both directions.", DescribeRole.Definition),
            Node("face-boundary", "faceBoundary", "Full boundary of the ambient face",
                "An ambient face point is in the face boundary when some ground label belonging to face has zero coordinate. Off-face zeros are excluded.", DescribeRole.Definition),
            Node("face-coordinate-homeomorph-boundary", "faceCoordinateHomeomorph_boundary", "Boundary compatibility",
                "Zero extension preserves and reflects the boundary condition over face labels, with the original ground-label witnesses retained.", DescribeRole.Theorem),
            Node("face-boundary-setoid", "faceBoundarySetoid", "Ambient full-boundary relation",
                "The original ambient face quotient identifies exactly equal representatives or two points on this face boundary.", DescribeRole.Definition),
            Node("ambient-boundary-homeomorph", "ambientBoundaryHomeomorph", "Original ambient quotient homeomorphism",
                "Restrict an original ambient representative to its face coordinates, apply Psi, and descend through the literal ambient face-boundary relation. The finite convex hull supplies compactness and the same exact-fiber argument gives the homeomorphism to the face-indexed Euclidean sphere.", DescribeRole.Definition),
            Node("shared-cardr", "cardR", "Real cardinality",
                "The real number obtained by casting the finite face-label cardinality, used by the current rational sphere formula.", DescribeRole.Definition),
            Node("shared-cardr-pos", "cardR_pos", "Positive nonempty cardinality",
                "For a nonempty finite label type, its real cardinality is positive.", DescribeRole.Theorem),
            Node("shared-cardr-ne", "cardR_ne", "Nonzero nonempty cardinality",
                "For a nonempty finite label type, its real cardinality is nonzero.", DescribeRole.Theorem),
            Node("shared-mincoord", "minCoord", "Face-coordinate minimum",
                "The finite attained minimum of the actual simplex coordinates over its own label type; it never includes ambient ghosts outside a face.", DescribeRole.Definition),
            Node("shared-sigma", "sigma", "The shared barycentric gauge",
                "Multiply the face-coordinate minimum by the real face-label cardinality.", DescribeRole.Definition),
            Node("shared-mincoord-attained", "minCoord_attained", "An actual minimum label",
                "Every literal finite nonempty simplex point has a label whose coordinate equals the minimum.", DescribeRole.Theorem),
            Node("shared-mincoord-le", "minCoord_le", "Minimum below every coordinate",
                "At every original simplex label the attained minimum is at most that coordinate.", DescribeRole.Theorem),
            Node("shared-sigma-nonneg", "sigma_nonneg", "Nonnegative barycentric gauge",
                "The common sigma gauge is nonnegative for every literal simplex point.", DescribeRole.Theorem),
            Node("shared-sigma-eq-zero-iff", "sigma_eq_zero_iff", "Full-boundary gauge equation",
                "For every nonempty simplex, sigma is zero exactly when some face-label coordinate is zero; the minimum is attained.", DescribeRole.Theorem),
            Node("shared-continuous-mincoord", "continuous_minCoord", "Continuous face-coordinate minimum",
                "The finite coordinate minimum is continuous in the actual L2 simplex topology.", DescribeRole.Theorem),
            Node("shared-vertex", "vertex", "A literal coordinate vertex",
                "The actual simplex point with coordinate one at the selected label and zero at every other label.", DescribeRole.Definition),
            Node("shared-vertex-boundary", "vertex_boundary", "A real boundary point when at least two labels exist",
                "For cardinality at least two, any literal coordinate vertex has a distinct face label of coordinate zero and hence belongs to the full boundary.", DescribeRole.Theorem),
            Paragraph(Text("The rational map, exact fiber criterion and non-south inverse require only a nonempty finite label type. Surjectivity and the reusable full-sphere quotient homeomorphism assume card(Λ)≥2. For card(Λ)=1 the standalone simplex quotient is a single point. The extra collapsed component needed for an attached-space S0 consumer, the disk collar, the literal attachment map and the universal graph supplier remain separate mathematical obligations.")))));

    private static DocumentBlock Node(string id, string declaration, string title, string prose,
        DescribeRole role) => Describe.Lean(
            DescribeId.Create(id), DeclarationHandle.Create(Prefix + declaration), H(title),
            role == DescribeRole.Definition ? StatementSource.WithoutFormula() : StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(SourceText(prose)), role);

    // TextRun is one line. Keep every quoted source line, including blank separators,
    // as typed text; this is commentary, never a substitute for a Lean projection.
    private static DocumentBlock SourceText(string value) => value.Contains('\n')
        ? new DocumentBlock.Section(H("Source text"), Blocks(Array.ConvertAll(
            value.Split('\n'), line => Paragraph(Text(line.Length == 0 ? "Definitions and proofs are in the paired Lean module." : line)))))
        : Paragraph(Text(value));
}
